using System.Security.Cryptography;
using System.Text;
using System.Text.Json;

namespace TheKrystalShip.KGSM.Dns.Anchor.Acme;

/// <summary>
/// The key this holder's ACME account is registered with.
/// </summary>
/// <remarks>
/// <para>
/// <b>One per holder, generated by the holder.</b> Accounts cost nothing to register, so a member that
/// takes the <c>dns</c> capability registers its own rather than being handed the previous holder's
/// key. No secret moves on failover, and a key never has to be copied anywhere.
/// </para>
/// <para>
/// A key that exists and cannot be read stops issuance rather than being replaced: replacing it would
/// silently register a second account, and whatever rate limits and history the first one carries
/// would be split between two identities nobody asked for.
/// </para>
/// </remarks>
internal sealed class AcmeAccountKey : IDisposable
{
    private readonly ECDsa _key;

    private AcmeAccountKey(ECDsa key)
    {
        _key = key;
        ECParameters p = key.ExportParameters(includePrivateParameters: false);
        Jwk = new AcmeJwk { X = Base64Url(p.Q.X!), Y = Base64Url(p.Q.Y!) };

        // RFC 7638: the thumbprint is the SHA-256 of the JWK's required members, lexically ordered, with
        // no whitespace. AcmeJwk declares them in that order, and the serializer writes no whitespace.
        byte[] canonical = JsonSerializer.SerializeToUtf8Bytes(Jwk, AcmeJsonContext.Default.AcmeJwk);
        Thumbprint = Base64Url(SHA256.HashData(canonical));
    }

    /// <summary>The public half, as the account is registered with it.</summary>
    public AcmeJwk Jwk { get; }

    /// <summary>The account key's thumbprint, which every key authorization carries.</summary>
    public string Thumbprint { get; }

    /// <summary>Read the key at a path, generating one when the path holds none.</summary>
    public static AcmeAccountKey LoadOrCreate(string path)
    {
        var key = ECDsa.Create(ECCurve.NamedCurves.nistP256);

        if (File.Exists(path))
        {
            key.ImportFromPem(File.ReadAllText(path));
            return new AcmeAccountKey(key);
        }

        string? directory = Path.GetDirectoryName(Path.GetFullPath(path));
        if (!string.IsNullOrEmpty(directory))
            Directory.CreateDirectory(directory);

        // Written readable by this account alone before a byte of the key is in it.
        var options = new FileStreamOptions { Mode = FileMode.CreateNew, Access = FileAccess.Write };
        if (!OperatingSystem.IsWindows())
            options.UnixCreateMode = UnixFileMode.UserRead | UnixFileMode.UserWrite;

        using (var stream = new FileStream(path, options))
        using (var writer = new StreamWriter(stream, new UTF8Encoding(false)))
        {
            writer.Write(key.ExportPkcs8PrivateKeyPem());
        }

        return new AcmeAccountKey(key);
    }

    /// <summary>Sign a JWS signing input. ES256 is the fixed-width r‖s form, which is .NET's default.</summary>
    public byte[] Sign(byte[] signingInput) => _key.SignData(signingInput, HashAlgorithmName.SHA256);

    /// <summary>
    /// The TXT value a DNS-01 challenge is answered with: the SHA-256 of the key authorization,
    /// base64url-encoded (RFC 8555 §8.4).
    /// </summary>
    public string Dns01Value(string token) =>
        Base64Url(SHA256.HashData(Encoding.ASCII.GetBytes(token + "." + Thumbprint)));

    public static string Base64Url(byte[] bytes) =>
        Convert.ToBase64String(bytes).TrimEnd('=').Replace('+', '-').Replace('/', '_');

    public void Dispose() => _key.Dispose();
}
